def first_item(items):              # O(1): one step, however long the list is
    return items[0]

def contains(items, target):        # O(n): may look at every item once
    for item in items:
        if item == target:
            return True
    return False

def has_duplicate(items):           # O(n^2): compares every pair
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            if items[i] == items[j]:
                return True
    return False

def has_duplicate_fast(items):      # O(n) time, O(n) extra space
    seen = set()
    for item in items:
        if item in seen:
            return True
        seen.add(item)
    return False

print(has_duplicate([1, 2, 3, 2]))       # True
print(has_duplicate_fast([1, 2, 3, 2]))  # True

function firstItem<T>(items: T[]): T | undefined {   // O(1)
  return items[0];
}

function contains<T>(items: T[], target: T): boolean { // O(n)
  for (const item of items) {
    if (item === target) return true;
  }
  return false;
}

function hasDuplicate<T>(items: T[]): boolean {        // O(n^2)
  for (let i = 0; i < items.length; i++) {
    for (let j = i + 1; j < items.length; j++) {
      if (items[i] === items[j]) return true;
    }
  }
  return false;
}

function hasDuplicateFast<T>(items: T[]): boolean {    // O(n) time, O(n) space
  const seen = new Set<T>();
  for (const item of items) {
    if (seen.has(item)) return true;
    seen.add(item);
  }
  return false;
}

console.log(hasDuplicate([1, 2, 3, 2]));     // true
console.log(hasDuplicateFast([1, 2, 3, 2])); // true
